  @apply mx-auto max-w-6xl flex justify-between items-center;
}

.siteNav h1 {
  @apply font-bold text-xl;
}

svg.logo {
  display: inline-block;
}

.brandLink {
  @apply text-heading no-underline hover:opacity-80 transition-opacity duration-200;
}

